local config = {
  ui_story_31170401_1_dialog_content = "Lihat, 'kan, Vice? Sudah kubilang Navigator kelihatannya sedang tidak sehat hari ini.",
  ui_story_31170401_2_dialog_content = "Wajah pucat, bibir pecah-pecah... Bahkan rambut PlayerName terlihat berantakan.",
  ui_story_31170401_3_dialog_content = "Kamu benar. Memang sudah berhari-hari Navigator tidak mau makan.",
  ui_story_31170401_4_dialog_content = "Hari ini juga sama... PlayerName tidak mengigit secuil pun rotinya tadi pagi.",
  ui_story_31170401_5_dialog_content = "Iya, belakangan ini aku sedang tidak nafsu makan... Entah kenapa rasanya aku sangat lemah...",
  ui_story_31170401_6_dialog_content = "Sini, biar kuperiksa.",
  ui_story_31170401_7_dialog_content = "Tidak demam, kok.",
  ui_story_31170401_8_dialog_content = "Tuan Gram...",
  ui_story_31170401_9_dialog_content = "Panggil saja \"Gram\".",
  ui_story_31170401_10_dialog_content = "G-Gram... Bisa tolong lepaskan kelopak mataku?",
  ui_story_31170401_11_dialog_content = "Bagian putih matamu juga tampak kurang sehat... Bagaimana tidurmu belakangan ini?",
  ui_story_31170401_12_dialog_content = "Aku ingat semalam lampu kamarmu masih menyala padahal sudah larut, Navigator.",
  ui_story_31170401_13_dialog_content = "Jam berapa kamu tidur semalam?",
  ui_story_31170401_14_dialog_content = "Entahlah... Aku hanya ingat sedang berbaring sebentar, lalu kalian berdua memanggilku.",
  ui_story_31170401_15_dialog_content = "Sepertinya aku tidur dua, tiga jam, mungkin?",
  ui_story_31170401_16_dialog_content = "Tapi, tidak apa-apa, kok! Sungguh! Aku sudah terbiasa belakangan ini. Aku hanya merasa sedikit capek saat bangun. Itu saja.",
  ui_story_31170401_17_dialog_content = "Sudah berapa lama kau seperti ini?",
  ui_story_31170401_18_dialog_content = "Kira-kira seminggu.",
  ui_story_31170401_19_dialog_content = "Sekitar waktu itu juga kamu mulai kehilangan nafsu makan.",
  ui_story_31170401_20_dialog_content = "Baiklah. Sebenarnya, aku pernah menjumpai hal ini. Kami menyebutnya <color=#FFB400>Body Function Disorder</color>, atau BFD.",
  ui_story_31170401_21_dialog_content = "Ini banyak terjadi pada prajurit baru. Untungnya, aku punya <color=#FFB400>obatnya</color>.",
  ui_story_31170401_22_dialog_content = "Vice, sepertinya PlayerName tidak bisa bekerja. Colossus-nya bagaimana?",
  ui_story_31170401_23_dialog_content = "Biar aku yang menangani tugas Navigator.",
  ui_story_31170401_24_dialog_content = "Obat... jenis apa? Apakah pahit?",
  ui_story_31170401_25_dialog_content = "Tidak sama sekali, tapi mungkin agak berat. Ayo kita coba.",
  ui_story_31170401_26_option_content = "Berat...?",
  ui_story_31170401_27_dialog_content = "Bagaimana mengonsumsi obat bisa melelahkan? Apakah saya harus makan pil yang sangat besar atau bagaimana?",
  ui_story_31170401_28_dialog_content = "Kalau saja semudah itu...",
  ui_story_31170401_29_dialog_content = "Obat ini akan memengaruhi setiap saraf dan otot tubuhmu dan meningkatkan sirkulasi darah secara drastis. Setelah meminumnya, kau akan merasa seperti terlahir kembali.",
  ui_story_31170401_30_option_content = "Coba meminumnya...?",
  ui_story_31170401_31_dialog_content = "Sepertinya lumayan juga, tapi kenapa kedengarannya sangat tidak enak?",
  ui_story_31170401_32_dialog_content = "Apakah rasanya sepedas wasabi atau semacamnya?",
  ui_story_31170401_33_dialog_content = "Tidak pedas, sih... tapi kau akan sangat berkeringat.",
  ui_story_31170401_34_dialog_content = "Dulu aku sering meminumnya... Pokoknya percaya sajalah kalau kubilang obat itu manjur.",
  ui_story_31170401_35_dialog_content = "Tapi, pertama-tama aku harus melihat seberapa berantakannya fungsi tubuhmu.",
  ui_story_31170401_36_dialog_content = "Cara mengujinya sederhana, kok.",
  ui_story_31170401_37_dialog_content = "Ujian macam apa?",
  ui_story_31170401_38_dialog_content = "Oh, sebenarnya macam-macam! Uji ketahanan, uji koordinasi tubuh bawah, uji keseimbangan, uji kekuatan lengan...",
  ui_story_31170401_39_dialog_content = "Kita lakukan semuanya satu demi satu!",
  ui_story_31170401_40_dialog_content = "Sekarang, mari kita mulai dengan menguji ketahanan fisikmu. Mengangkat ember air.",
  ui_story_31170401_41_dialog_content = "Haah... Haah... Haah...",
  ui_story_31170401_42_dialog_content = "Masih ada dua ember lagi! Ayo, jangan berhenti!",
  ui_story_31170401_43_dialog_content = "Haah... Haah... Haah...",
  ui_story_31170401_44_dialog_content = "Kita bisa menguji kekuatan lenganmu dengan memotong kayu. Gerakannya cukup sederhana: Angkat lenganmu tinggi-tinggi, lalu ayunkan ke bawah dengan keras!",
  ui_story_31170401_45_dialog_content = "Yang penting, lakukan dengan cepat dan akurat!",
  ui_story_31170401_46_dialog_content = "Ingat! Setiap kayu harus dipecah menjadi empat potong berukuran sama!",
  ui_story_31170401_47_dialog_content = "Siap, Pak...",
  ui_story_31170401_48_dialog_content = "<color=#e8d9bb>Dor!</color>",
  ui_story_31170401_49_dialog_content = "<color=#e8d9bb>Dor!</color>",
  ui_story_31170401_X49_dialog_content = "Selanjutnya, memetik kacang polong!",
  ui_story_31170401_50_dialog_content = "Bahuku nyeri sekali...",
  ui_story_31170401_51_dialog_content = "Anak-anak zaman sekarang memang kurang latihan fisik. Lihat saja dirimu! Belum apa-apa saja lenganmu sudah gemetaran seperti kaki bayi rusa!",
  ui_story_31170401_52_dialog_content = "Jangan berhenti! Kau masih harus memetik kacang polong. Cepat!",
  ui_story_31170401_53_dialog_content = "Sebanyak ini...? Jumlahnya terlalu banyak untuk dipetik seorang diri...",
  ui_story_31170401_54_dialog_content = "Musuh tidak akan menoleransi keluh kesah dan alasanmu dalam pertempuran sungguhan.",
  ui_story_31170401_55_dialog_content = "Kau ada benarnya, tapi tetap saja...",
  ui_story_31170401_56_dialog_content = "Kamu harus percaya pada dirimu... pada keteguhan dan ketekunanmu! Ingat, kamu sudah berjanji akan menyelesaikan ini!",
  ui_story_31170401_57_dialog_content = "Sekarang cepat petik, jangan sia-siakan ujian ini!",
  ui_story_31170401_58_dialog_content = "*Hiks* Kenapa aku harus melakukan ini...?",
  ui_story_31170401_59_dialog_content = "Kalau tahu bakal begini, aku tak mau mengikuti ujian ini... Padahal aku cuma tidak nafsu makan...",
  ui_story_31170401_60_dialog_content = "Masih ada lima potong daging lagi! Cincang terus!",
  ui_story_31170401_61_dialog_content = "Ujian macam apa ini, Gram?! Kau hanya menyuruhku mengerjakan tugasmu, 'kan?!",
  ui_story_31170401_62_dialog_content = "Mengangkat air, memotong kayu, memetik kacang polong... Sekarang mencincang daging? Kau hanya menjadikanku asistenmu!",
  ui_story_31170401_63_dialog_content = "Heh... Tidak semua orang bisa jadi asistenku, tahu?",
  ui_story_31170401_64_dialog_content = "Eh, tunggu... Bau lezat apa itu...?",
  ui_story_31170401_65_dialog_content = "Berkat ujian kita barusan, aku bisa memahami kondisi tubuhmu dan menyiapkan ini untukmu.",
  ui_story_31170401_66_dialog_content = "Nih.",
  ui_story_31170401_67_dialog_content = "Nasi goreng dengan daging dan kacang polong...?",
  ui_story_31170401_68_dialog_content = "(Blubuk, blubuk)",
  ui_story_31170401_69_dialog_content = "Kelihatannya nafsu makanmu sudah kembali. Sana, bawa makanan ini ke kamarmu...",
  ui_story_31170401_70_dialog_content = "*Nyam, nyam*",
  ui_story_31170401_71_dialog_content = "Lezat sekali!!",
  ui_story_31170401_72_dialog_content = "Kok bisa sih ada makanan selezat ini di dunia?! Daging ini digoreng sempurna!",
  ui_story_31170401_73_dialog_content = "Dagingnya berlemak tetapi tidak terlalu berminyak, kacangnya renyah dan beraroma, lalu setiap butir nasi panggang menonjol dengan sempurna dari yang lain...",
  ui_story_31170401_74_dialog_content = "*Nyam, nyam*",
  ui_story_31170401_75_dialog_content = "Yah, kau boleh memakannya di sini. Sepertinya omonganku tidak kaudengarkan, ya.",
  ui_story_31170401_76_dialog_content = "*Makan dengan lahap* Kok ada makanan selezat ini...?! *Nyam, nyam*",
  ui_story_31170401_77_dialog_content = "Hei, pelan-pelan saja. Jangan bicara dengan mulut penuh!",
  ui_story_31170401_78_dialog_content = "*Hoik*",
  ui_story_31170401_79_dialog_content = "Kau yang memasak nasi goreng itu, Gram? *Hoik* Aku tak tahu... bahwa kau ini koki andal!",
  ui_story_31170401_80_dialog_content = "Hahaha! Aku menghabiskan banyak waktu di masa militerku bekerja di ruang makan, Nak! Ini bukan apa-apa, aku yakin aku sudah memberi makan setiap orang di Undercities setidaknya satu kali!",
  ui_story_31170401_81_dialog_content = "Tak kusangka... *Hoik*",
  ui_story_31170401_82_dialog_content = "Ehem... Aku senang kalau kau suka, tapi kau tak perlu menjilat piringnya sampai bersih, lho.",
  ui_story_31170401_83_dialog_content = "Oh, iya! Kapan harus kuminum obatnya, Gram?",
  ui_story_31170401_84_dialog_content = "Obatmu? Kita bicarakan besok saja.",
  ui_story_31170401_85_dialog_content = "Sekarang sebaiknya kamu mandi lalu pergi tidur.",
  ui_story_31170401_86_dialog_content = "Baik, aku memang merasa cukup lelah... Aku akan melakukannya, Gram.",
  ui_story_31170401_87_dialog_content = "Selamat pagi, PlayerName!",
  ui_story_31170401_88_dialog_content = "Hei, Vice... Selamat pagi!",
  ui_story_31170401_89_dialog_content = "Hari ini kamu bangun pagi, PlayerName. Sudah baikan?",
  ui_story_31170401_90_dialog_content = "Selamat pagi, Gram.",
  ui_story_31170401_91_dialog_content = "Ya, jauh lebih baik! Saat bangun tadi, aku merasa sangat segar dan penuh semangat. Rasanya aku tidak butuh obat hari ini!",
  ui_story_31170401_92_dialog_content = "Anak-anak muda memang cepat pulih... Sepertinya obatku manjur!",
  ui_story_31170401_93_dialog_content = "Hah?",
  ui_story_31170401_94_dialog_content = "Intinya, kau sudah minum obat kemarin. Paham?",
  ui_story_31170401_95_option_content = "Aku paham.",
  ui_story_31170401_96_dialog_content = "Ujian kemarin hanya untuk olahraga, 'kan?",
  ui_story_31170401_97_dialog_content = "Lalu saat kita makan... itu memang sudah waktunya makan malam, 'kan?",
  ui_story_31170401_98_dialog_content = "Aku langsung tertidur karena merasa lelah dan kenyang... aku tidur sampai delapan jam.",
  ui_story_31170401_99_dialog_content = "Artinya, <color=#FFB400>obat terbaik adalah olahraga teratur dan rutinitas harian yang baik</color>!",
  ui_story_31170401_100_option_content = "Tidak juga...",
  ui_story_31170401_101_dialog_content = "Ehem, kamu ingat jam berapa kamu makan malam?",
  ui_story_31170401_102_dialog_content = "Sepertinya sudah sore...",
  ui_story_31170401_103_dialog_content = "Ujian yang kamu lakukan di siang hari... sebenarnya hanya kegiatan fisik.",
  ui_story_31170401_104_dialog_content = "Dengan makan malam yang bergizi dan istirahat yang cukup, tubuhmu kembali bugar!",
  ui_story_31170401_105_dialog_content = "Aku paham sekarang! <color=#FFB400>Obat terbaik adalah olahraga teratur dan rutinitas harian yang baik</color>.",
  ui_story_31170401_106_dialog_content = "Benar sekali!",
  ui_story_31170401_107_dialog_content = "Terima kasih, Gram!",
  ui_story_31170401_108_dialog_content = "Syukurlah kalau kau sudah baikan. Ingat, tubuhmu adalah tanggung jawabmu. Tapi, jangan lupa bahwa orang lain juga mengandalkanmu.",
  ui_story_31170401_109_dialog_content = "Terutama soal pertempuran. Jangan sampai tubuhmu seperti itu lagi, ya? Ini demi teman-temanmu. Paham?",
  ui_story_31170401_110_option_content = "Aku paham!",
  ui_story_31170401_111_dialog_content = "Kalau aku sampai kelelahan dan lemah, kemampuanku memberi perintah pasti akan sangat terpengaruh.",
  ui_story_31170401_112_dialog_content = "Kalau begitu, kesalahan terkecil pun bisa fatal. Bahkan mungkin kau harus membayarnya dengan nyawa...",
  ui_story_31170401_113_dialog_content = "Kau benar... Mulai sekarang aku akan menjaga diriku dengan lebih baik!",
  ui_story_31170401_114_option_content = "Tapi, kenapa?",
  ui_story_31170401_115_dialog_content = "Kau bertugas untuk memberi perintah dalam pertempuran. Ingat, 'kan?",
  ui_story_31170401_116_dialog_content = "Kalau terjadi sesuatu... Mungkin saja...",
  ui_story_31170401_117_dialog_content = "Konsekuensinya tidak main-main.",
  ui_story_31170401_118_dialog_content = "Aku mengerti. Tak akan kubiarkan tubuhku jadi seperti itu lagi.",
  ui_story_31170401_119_dialog_content = "Baiklah.",
  ui_story_31170401_120_dialog_content = "Karena sekarang kau sudah sembuh, kurasa sudah waktunya aku pergi.",
  ui_story_31170401_121_dialog_content = "Cepat sekali perginya... Aku belum sempat berterima kasih dengan baik padanya.",
  ui_story_31170401_122_dialog_content = "Gram bukan orang yang suka mendapat ucapan terima kasih. Selama kau sudah sehat, itu sudah lebih dari cukup baginya.",
  ui_story_31170401_123_dialog_content = "Jangan tertipu oleh sikap santainya. Dia sangat memperhatikan kesejahteraan teman-temannya.",
  ui_story_31170401_124_dialog_content = "<color=#FFB400>Soldier's Fried Rice</color> yang dibuatnya untukmu adalah masakan terbaiknya. Penuh nutrisi dan sangat bergizi!",
  ui_story_31170401_125_dialog_content = "Oh, jadi itu namanya... Rasanya sangat lezat! Mana mungkin aku bakal melupakan rasanya...",
  ui_story_31170401_126_dialog_content = "Sebelum dia memasak hidangan itu untukku, kupikir Gram hanyalah seorang veteran biasa yang bertugas sebagai manajer logistik.",
  ui_story_31170401_127_dialog_content = "Dia memiliki sejarah yang panjang dan penuh peristiwa... Ketika pertama kali bergabung dengan militer, dia bekerja sebagai koki selama beberapa tahun sebelum beralih ke garis pertahanan untuk menghadapi serangan Eclipsite...",
  ui_story_31170401_128_dialog_content = "Setelah pensiun dari militer, dia mulai bekerja di bidang logistik dan kembali menekuni kegemarannya memasak. Pengalaman dan latihan bertahun-tahun yang luar biasa!",
  ui_story_31170401_129_dialog_content = "Tapi, Soldier's Fried Rice buatannya disajikan untuk orang-orang sakit. Aku juga baru menyantapnya satu kali seumur hidup.",
  ui_story_31170401_130_dialog_content = "Bagaimana kalau aku bergadang selama beberapa hari agar dia memasaknya lagi untukku, ya?",
  ui_story_31170401_131_dialog_content = "Sepadan dengan pengorbanannya, 'kan, PlayerName?",
  ui_story_31170401_132_dialog_content = "S-sepertinya tidak juga…",
  ui_story_31170401_133_dialog_content = "Meskipun Soldier's Fried Rice terasa sangat lezat, ujiannya terlalu melelahkan...",
  ui_story_31170601_1_dialog_content = "<color=#e8d9bb>Ciprat, ciprat—</color>",
  ui_story_31170601_2_dialog_content = "Tidak, tunggu saja! Aku belum akan turun—",
  ui_story_31170601_3_dialog_content = "<size=45>Tidak jatuh—Aaaaahhh!</size>",
  ui_story_31170601_4_dialog_content = "<size=45>TIDAAAK—</size>",
  ui_story_31170601_5_dialog_content = "<size=45>Aaaaahhh—</size>",
  ui_story_31170601_6_dialog_content = "<color=#e8d9bb>Lima belas menit yang lalu</color>",
  ui_story_31170601_7_dialog_content = "<color=#e8d9bb>Splish, splash—</color>",
  ui_story_31170601_8_dialog_content = "Oh, udara yang menyegarkan. Sudah lama sekali aku tidak datang ke lembah yang begitu tenang dan indah ini.",
  ui_story_31170601_9_dialog_content = "Tapi apakah ini tujuan akhir kita? Saya kira ini latihan? Atau...",
  ui_story_31170601_10_dialog_content = "Akhirnya kamu menunjukkan belas kasihan dan mengambil kesempatan untuk mengajakku berwisata?",
  ui_story_31170601_11_dialog_content = "<color=#e8d9bb>Guyuran!</color>",
  ui_story_31170601_12_dialog_content = "Gram?!",
  ui_story_31170601_13_dialog_content = "D-Di mana kamu? Kamu tidak sengaja jatuh ke danau, kan? Jangan bikin aku panik di sini!",
  ui_story_31170601_14_dialog_content = "Tahu kan, nama Gram dan \"terjatuh secara tidak sengaja\" tidak seharusnya ada dalam satu kalimat. Bagaimana kalau kamu bergabung denganku?",
  ui_story_31170601_15_dialog_content = "Hah? Tunggu, jangan tarik aku ke dalam air—!",
  ui_story_31170601_16_dialog_content = "Buka matamu dan lihat, Nak. Ini bahkan tidak sampai setinggi lutut.",
  ui_story_31170601_17_dialog_content = "Kamu benar... Haha, memang menyenangkan bermain air seperti ini kadang-kadang.",
  ui_story_31170601_18_dialog_content = "Aku tahu kamu bakal suka ini.",
  ui_story_31170601_19_dialog_content = "Tapi jangan salah paham, ini adalah tempat latihan alami kami.",
  ui_story_31170601_20_dialog_content = "Lihat air terjun itu? Ayo berdiri di sana!",
  ui_story_31170601_21_dialog_content = "Latihan macam apa ini?",
  ui_story_31170601_22_dialog_content = "Sebagai prajurit garis depan, kamu harus tetap tenang dan bertahan hingga akhir, tak peduli apa yang menghadangmu.",
  ui_story_31170601_23_dialog_content = "Mempertahankan postur Anda di bawah air terjun yang deras tanpa bergerak adalah cara terbaik untuk mengasah disiplin tersebut.",
  ui_story_31170601_24_dialog_content = "Saya menyebut pelatihan ini, \"Prajurit Tak Pernah Jatuh.\"",
  ui_story_31170601_25_dialog_content = "Ini pertarungan melawan alam sekaligus antara kamu dan aku.",
  ui_story_31170601_26_dialog_content = "Ayo, PlayerName! Siapa pun yang pertama kali bangkit dari tempat duduknya akan bertanggung jawab untuk memasak hari ini.",
  ui_story_31170601_27_dialog_content = "Apa? Tapi aku sudah sangat ingin mencicipi masakanmu dan itulah mengapa aku setuju untuk latihan ini!",
  ui_story_31170601_28_dialog_content = "Jadi kamu tidak merasa punya kesempatan untuk mengalahkanku?",
  ui_story_31170601_29_option_content = "Aku akan memberi diriku kesempatan dengan cara apa pun!",
  ui_story_31170601_30_dialog_content = "Aku harus percaya ada kesempatan, meskipun kecil. Jika tidak, aku sama sekali tidak akan bisa mengalahkanmu!",
  ui_story_31170601_31_option_content = "Itu karena kamu terlalu tangguh untukku!",
  ui_story_31170601_32_dialog_content = "Namun, saya harus mencobanya.",
  ui_story_31170601_33_dialog_content = "Aku akan mencoba masakanmu!",
  ui_story_31170601_34_dialog_content = "<color=#e8d9bb>Splish, splash—</color>",
  ui_story_31170601_35_dialog_content = "Ahh! Dampaknya lebih besar dari yang kukira...",
  ui_story_31170601_36_dialog_content = "Aku hampir... mencapai batasku...",
  ui_story_31170601_37_dialog_content = "No, just hang on! I'm not going down yet—",
  ui_story_31170601_38_dialog_content = "<size=45>Not going down—Aaaaahhh!</size>",
  ui_story_31170601_39_dialog_content = "<size=45>NOOOO—</size>",
  ui_story_31170601_40_dialog_content = "<size=45>Aaaaahhh—</size>",
  ui_story_31170601_41_dialog_content = "<size=45><color=#e8d9bb>Guyuran!</color></size>",
  ui_story_31170601_42_dialog_content = "Hahaha! Lumayan juga, Nak, kamu bertahan lebih lama dari yang kubayangkan.",
  ui_story_31170601_43_dialog_content = "(Bagaimana bisa Gram masih berdiri seperti tembok di air terjun setelah waktu yang begitu lama?)",
  ui_story_31170601_44_dialog_content = "(Hehh, memang sudah diduga sih. Aku bahkan tidak sebanding dengannya...)",
  ui_story_31170601_45_dialog_content = "Baiklah, makan malam sekarang ada di tanganmu!",
  ui_story_31170601_46_dialog_content = "Latihan ini terlalu sulit bagiku. Mustahil bagiku untuk menang tanpa keunggulan fisik dan kekuatan yang kamu miliki.",
  ui_story_31170601_47_dialog_content = "PlayerName, kamu pernah ke garis depan Illumina, jadi kamu tahu kita punya orang-orang kurus di tentara.",
  ui_story_31170601_48_dialog_content = "Dan ketika mereka bertarung, mereka bertarung sehebat saya. Tahukah kamu mengapa?",
  ui_story_31170601_49_dialog_content = "... Ya, Gram, aku tahu apa yang kamu maksud. Aku tak akan membuat alasan lagi.",
  ui_story_31170601_50_dialog_content = "Kamu selalu menemukan sumber masalah dalam waktu singkat, itulah mengapa aku setuju untuk mengajakmu berlatih di luar.",
  ui_story_31170601_51_dialog_content = "Sejak menjadi instruktur latihan, aku semakin banyak melihat anak muda yang berkualitas.",
  ui_story_31170601_52_dialog_content = "Sebagai gantinya, aku akan membuat tuntutan yang lebih keras dari sebelumnya, jadi kamu harus memberikan yang terbaik!",
  ui_story_31170601_53_dialog_content = "Aku hampir lupa bahwa kamu sekarang jadi instruktur untuk anggota baru!",
  ui_story_31170601_54_dialog_content = "Tidak heran ada sesuatu yang berbeda tentang kamu... Ada apa sebenarnya?",
  ui_story_31170601_55_dialog_content = "Kamu tertarik?",
  ui_story_31170601_56_dialog_content = "Lalu buatlah makan malam sekarang. Pastikan kamu melakukan tes kondisi fisik yang sudah aku tunjukkan sebelumnya.",
  ui_story_31170601_57_dialog_content = "Uji kondisi fisik? Maksudmu rutinitas olahraga sebelum memasak?",
  ui_story_31170601_58_dialog_content = "Tidak bisa lepas dari rutinitasmu bahkan ketika aku kalah, ya...",
  ui_story_31170601_59_dialog_content = "<color=#e8d9bb>Beberapa waktu kemudian</color>",
  ui_story_31170601_60_dialog_content = "*hoik*",
  ui_story_31170601_61_dialog_content = "Tak menyangka mencicipi makanan enak di alam terbuka bisa begitu menyenangkan.",
  ui_story_31170601_62_dialog_content = "Ini adalah kebahagiaan ganda pada tingkat spiritual dan fisik yang hanya bisa Anda dapatkan setelah menaruh seluruh usaha Anda dalam pelatihan.",
  ui_story_31170601_63_dialog_content = "Jadi, bagaimana kalau kamu sering keluar bersamaku?",
  ui_story_31170601_64_dialog_content = "Maksudmu, benar-benar ikut keluar dan berlatih bersamamu, kan?",
  ui_story_31170601_65_dialog_content = "Oh, iya, Gram, ngomong-ngomong, ada kejadian menarik nggak?",
  ui_story_31170601_66_dialog_content = "Aku sudah memberitahumu apa yang paling menonjol dalam ingatanku. Sedangkan untuk sisanya...",
  ui_story_31170601_67_dialog_content = "Atasan mengubah peralatan reguler semua orang lagi. Revy pergi menjalankan misi sendiri. Ansia akhirnya menemukan saklar untuk pengeras suara...",
  ui_story_31170601_68_dialog_content = "Dan aku, akhirnya mengerti pilihan yang Brent buat.",
  ui_story_31170601_69_dialog_content = "Melihat semua anak muda yang kukenal tumbuh begitu cepat rasanya menyenangkan. Aku lebih bahagia dan bangga daripada memenangkan pertempuran.",
  ui_story_31170601_70_dialog_content = "Meskipun kadang aku mendapat kabar buruk dan harus menghadiri beberapa pemakaman.",
  ui_story_31170601_71_dialog_content = "Melihat nama-nama prajurit yang saya latih di batu nisan memang menimbulkan keraguan apakah saya harus terus menjadi instruktur.",
  ui_story_31170601_72_dialog_content = "Dalam kasusku atau Brent, kami yang pemurung hidup cukup lama sehingga tidak menyesal sama sekali mengorbankan diri kami.",
  ui_story_31170601_73_dialog_content = "Namun, setiap rekrutan baru sama bersihnya seperti selembar kertas baru.",
  ui_story_31170601_74_dialog_content = "Aku tak tahan melihat anak-anak muda itu kehilangan nyawa mereka... Kau tahu, Brent akan memarahiku karena berpikir seperti ini.",
  ui_story_31170601_75_dialog_content = "Tapi apa yang bisa kamu lakukan, selain menjadi tangguh, lalu semakin tangguh saat aku melatih mereka?",
  ui_story_31170601_76_dialog_content = "Ubah para pemula menjadi prajurit sebelum mereka masuk medan perang agar mereka tidak perlu melakukan pengorbanan yang tidak perlu.",
  ui_story_31170601_77_dialog_content = "Kusadari sekarang maksudmu baik... Tapi, pernahkah kamu pertimbangkan untuk kembali ke garis depan?",
  ui_story_31170601_78_dialog_content = "Dengan sehebat dan tak terkalahkan dirimu, kamu bisa dengan mudah menjadi panutan bagi prajurit, bahkan sosok yang setara dengan para komandan!",
  ui_story_31170601_79_dialog_content = "Tidak masalah. Aku sudah bersumpah sejak dulu untuk menyelesaikan apa yang Brent tidak bisa. Dan...",
  ui_story_31170601_80_dialog_content = "\"Warriors never fall\" tidak berarti seorang prajurit yang selalu tak terkalahkan dan tak tergoyahkan.",
  ui_story_31170601_81_dialog_content = "Tapi bukankah kamu sendiri juga salah satunya?",
  ui_story_31170601_82_dialog_content = "Aku adalah Aurorian fana dengan kelemahan sendiri juga. Pejuang yang benar-benar tak terkalahkan dan tak tergoyahkan memang tidak ada.",
  ui_story_31170601_83_dialog_content = "Tapi \"prajurit tidak pernah jatuh\" bukanlah slogan yang kugunakan untuk mengecoh kamu.",
  ui_story_31170601_84_dialog_content = "Mungkin gambaran kecilnya adalah ribuan dan ribuan prajurit pada akhirnya akan gugur dalam pertempuran.",
  ui_story_31170601_85_dialog_content = "Tetapi gambaran besarnya adalah akan ada ribuan dan ribuan lagi yang akan menggantikan tempat mereka!",
  ui_story_31170601_86_dialog_content = "Itulah arti sebenarnya dari \"prajurit tak pernah jatuh\"!",
  ui_story_31170601_87_dialog_content = "Wow, kamu baru saja berbicara sangat mendalam dengan cepat...",
  ui_story_31170601_88_dialog_content = "Mungkin itu karena kamu sudah melatih orang-orang untuk beberapa waktu.",
  ui_story_31170601_89_dialog_content = "Ya, dan ada sesuatu yang sudah kupikirkan cukup lama sekarang...",
  ui_story_31170601_90_dialog_content = "Kamu harus mengasah atribut fisik dan kemampuan psikis secara bersamaan.",
  ui_story_31170601_91_dialog_content = "I-Itu kedengarannya sulit...",
  ui_story_31170601_92_dialog_content = "Tapi tidak masalah! Jika aku jatuh, aku akan segera bangkit lagi, karena...",
  ui_story_31170601_93_dialog_content = "Prajurit! Tak! Akan! Jatuh!",
  ui_story_31170601_94_dialog_content = "Hahaha, baiklah! Kau cepat belajar, nak!"
}
return config
